import { useMutation, useQueryClient } from "@tanstack/react-query";
import { saveProfile } from "../api/profile";
import { toast } from "../ui/toast";

export const ProfileForm = ({ profile }: { profile: { id: string; name: string } }) => {
  const queryClient = useQueryClient();
  const save = useMutation({ mutationFn: saveProfile });

  const onSubmit = (name: string) => {
    save.mutate(
      { id: profile.id, name },
      {
        onSuccess: () => {
          toast("Saved");
          queryClient.invalidateQueries({ queryKey: ["profile", profile.id] });
        },
      },
    );
  };

  return <button onClick={() => onSubmit("Ada")}>Save</button>;
};

import { useQueryClient } from "@tanstack/react-query";
import { useUpdateLabels } from "../state/labels";

export function LabelPicker({ postId, labels }) {
  const queryClient = useQueryClient();
  const { mutate: updateLabels } = useUpdateLabels();

  function choose(label) {
    updateLabels(
      { postId, labels: [...labels, label] },
      {
        onSettled() {
          queryClient.setQueryData(["post", postId], (old) => ({ ...old, labels: [...labels, label] }));
        },
      },
    );
  }

  return <ul>{labels.map((l) => <li key={l} onClick={() => choose(l)}>{l}</li>)}</ul>;
}

import { trpc } from "@acme/trpc/react";

export function ScheduleList() {
  const utils = trpc.useUtils();
  const bulkUpdate = trpc.viewer.schedules.bulkUpdate.useMutation();

  const applyDefault = (ids: number[], done: () => void) => {
    bulkUpdate.mutate(
      { ids },
      {
        onSuccess: () => {
          utils.viewer.schedules.list.invalidate();
          done();
        },
      },
    );
  };

  return <button onClick={() => applyDefault([1], () => undefined)}>Apply</button>;
}

import * as React from "react";
import { useQueryClient } from "react-query";
import { useCancelPlan } from "./mutations";

function CancelPlan({ planId }: { planId: string }) {
  const queryClient = useQueryClient();
  const cancel = useCancelPlan();

  const onClick = React.useCallback(async () => {
    await cancel.mutateAsync(planId, {
      onError: () => queryClient.resetQueries({ queryKey: ["plan", planId] }),
    });
  }, [cancel, planId, queryClient]);

  return <button onClick={onClick}>Cancel plan</button>;
}

export default CancelPlan;

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { sendInvite } from "./api";

export const InviteRow = ({ email }: { email: string }) => {
  const queryClient = useQueryClient();
  const { mutate } = useMutation({ mutationFn: sendInvite });

  return (
    <button
      onClick={() =>
        mutate(email, {
          onSuccess: async () => {
            await queryClient.refetchQueries({ queryKey: ["invites"] });
          },
        })
      }
    >
      Invite
    </button>
  );
};

import { useQueryClient } from "@tanstack/react-query";
import { useDeleteDraft } from "./useDeleteDraft";

export function useRemoveDraft() {
  const queryClient = useQueryClient();
  const remove = useDeleteDraft();
  return (id: string) =>
    remove.mutate(id, {
      onSuccess: () => queryClient.removeQueries({ queryKey: ["draft", id] }),
    });
}

import { api } from "~/utils/api";

export default function PostActions({ id }: { id: string }) {
  const archive = api.post.archive.useMutation();
  const ctx = api.useContext();

  return (
    <button
      onClick={() =>
        archive.mutate(
          { id },
          {
            onSuccess(data) {
              ctx.post.byId.setData({ id }, data);
            },
          },
        )
      }
    >
      Archive
    </button>
  );
}

