import { useQueryClient, type MutateOptions } from "@tanstack/react-query";
import { useSaveNote } from "./hooks";

export function Satisfies({ id }: { id: string }) {
  const qc = useQueryClient();
  const save = useSaveNote();
  const run = () =>
    save.mutate(id, ({
      onSettled: () => qc.setQueryData(["note", id], null),
    } satisfies MutateOptions<void, Error, string>));
  return <button onClick={run}>Save</button>;
}

