    save.mutate(
      { id: profile.id, name },
      {
        onSuccess: () => {
          toast("Saved");
          onClose();
        },
      },
    );
  };

  return <button onClick={() => onSubmit("Ada")}>Save</button>;
};

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { saveProfile } from "../api/profile";

export function useSaveProfile() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: saveProfile,
    onSettled() {
      queryClient.setQueryData(["profile"], undefined);
      return queryClient.invalidateQueries({ queryKey: ["profile"] });
    },
  });
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { forgetFact } from "./api";
import { toast } from "../ui/toast";

export function FactRow({ id }: { id: string }) {
  const queryClient = useQueryClient();
  const forget = useMutation({ mutationFn: forgetFact });

  return (
    <button
      onClick={() =>
        forget.mutate(id, {
          onSuccess: () => {
            toast("Forgotten", {
              action: { label: "Reload", onClick: () => queryClient.invalidateQueries({ queryKey: ["facts"] }) },
            });
          },
        })
      }
    >
      Forget
    </button>
  );
}

